135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        List<String> missingFields = new ArrayList<>();
139	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
140	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
141	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
142	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
143	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
144	        boolean hasStructuredAddress = !normalizedAddressLine1.isEmpty();
145	        String normalizedAddress = hasStructuredAddress
146	            ? composeAddress(normalizedAddressLine1, normalizedAddressLine2)
147	            : normalizedFlatAddress;
148	        requireNonBlank(missingFields, "address", normalizedAddress);
149	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
150	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
151	        if (!missingFields.isEmpty()) {
152	            throw new MissingRequiredFieldsException(missingFields);
153	        }
154	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
155	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
156	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
157	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
158	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
159	        requireDailyLimitNotReached(registrationDate);
160	        requireCityBelowCapacity(ownerFieldsDto.getCity());
161	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
162	        ownerFieldsDto.setTelephone(normalizedTelephone);
163	        if (ownerFieldsDto.getEmail() != null) {
164	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
165	        }
166	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
167	        HttpHeaders headers = new HttpHeaders();
168	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
169	        owner.setAddress(normalizedAddress);
170	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
171	        owner.setAddressLine2(hasStructuredAddress && !normalizedAddressLine2.isEmpty()
172	            ? normalizedAddressLine2 : null);
