277	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
278	            }
279	        }
280	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
281	    }
282	
283	    /**
284	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
285	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
286	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
287	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}).
288	     *
289	     * <p>When the computed code collides with an existing owner's {@code customerCode}, it is
290	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
291	     * unique (e.g. {@code NSW-1A2B3C4D-2}); the de-duplicated code is returned. Absent a collision the
292	     * base region-and-hash code is returned unchanged.
293	     *
294	     * @param owner the owner being created, with its region-determining postcode and city populated
295	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
296	     * @return the (de-duplicated) region-and-hash customer code for the owner being created
297	     */
298	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
299	        String region = ownerMapper.toRegion(owner);
300	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
301	        String baseCode = region + "-" + hash8;
302	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
303	            .map(Owner::getCustomerCode)
304	            .filter(java.util.Objects::nonNull)
305	            .collect(java.util.stream.Collectors.toSet());
306	        if (!existingCodes.contains(baseCode)) {
307	            return baseCode;
308	        }
309	        int n = 2;
310	        while (existingCodes.contains(baseCode + "-" + n)) {
311	            n++;
312	        }
313	        return baseCode + "-" + n;
314	    }
315	
316	    /**
317	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
318	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
319	     */
320	    private static String sha256Hex8(String value) {
321	        try {
322	            byte[] digest = MessageDigest.getInstance("SHA-256")
323	                .digest(value.getBytes(StandardCharsets.UTF_8));
324	            StringBuilder sb = new StringBuilder();
325	            for (byte b : digest) {
326	                sb.append(String.format("%02X", b));
327	            }
328	            return sb.substring(0, 8);
329	        }
330	        catch (NoSuchAlgorithmException e) {
331	            throw new IllegalStateException("SHA-256 not available", e);
332	        }
333	    }
334	
335	    /**
336	     * Counts the existing owners (those already persisted before this create) whose first and last
337	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
338	     * the new owner as its {@code namesakeCount} and echoed back on reads.
339	     *
340	     * @param firstName the incoming owner's first name (already validated non-blank)
341	     * @param lastName the incoming owner's last name (already validated non-blank)
342	     * @return the number of existing namesakes sharing both names case-insensitively
343	     */
344	    private int countNamesakes(String firstName, String lastName) {
345	        return (int) this.clinicService.findAllOwners().stream()
346	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
347	                && lastName.equalsIgnoreCase(existing.getLastName()))
348	            .count();
349	    }
350	
351	    /**
352	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
353	     * whitespace-only), so the caller can reject the request listing every offending field.
354	     */
355	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
356	        if (value == null || value.isBlank()) {
357	            missingFields.add(fieldName);
358	        }
359	    }
360	
361	    /**
362	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
363	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
364	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
365	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
366	     * {@code "+61412345678"}.
367	     *
368	     * @param telephone the raw telephone value from the request
369	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
370	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
371	     */
372	    private static String normalizeTelephone(String telephone) {
373	        String e164 = toE164(telephone);
374	        if (e164 == null) {
375	            throw new InvalidFieldValueException("telephone",
376	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
377	        }
378	        return e164;
379	    }
380	
381	    /**
382	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
383	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
384	     * owners' stored numbers when detecting duplicates.
385	     */
386	    private static String toE164(String telephone) {
387	        if (telephone == null) {
388	            return null;
389	        }
390	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
391	        String digits;
392	        if (cleaned.startsWith("+")) {
393	            digits = cleaned.substring(1);
394	        } else {
395	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
396	            digits = "61" + national;
397	        }
398	        if (!digits.matches("[0-9]{8,15}")) {
399	            return null;
400	        }
401	        if (!hasValidNationalLength(digits)) {
402	            return null;
403	        }
404	        return "+" + digits;
405	    }
406	
407	    /**
408	     * Checks the national-number length against the country code for the country codes that pin one.
409	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
410	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
411	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
412	     */
413	    private static boolean hasValidNationalLength(String digits) {
414	        if (digits.startsWith("61")) {
415	            return digits.length() - 2 == 9;
416	        }
417	        if (digits.startsWith("1")) {
418	            return digits.length() - 1 == 10;
419	        }
420	        return true;
421	    }
422	
423	    /**
424	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
425	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
426	     *
427	     * @param email the raw email value from the request (already known to be non-null)
428	     * @return the lower-cased email to be stored and returned
429	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
430	     */
431	    private static String normalizeEmail(String email) {
432	        String trimmed = email.trim();
433	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
434	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
435	        }
436	        String canonical = trimmed.toLowerCase(Locale.ROOT);
437	        String domain = canonical.substring(canonical.indexOf('@') + 1);
438	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
439	            throw new InvalidFieldValueException("email", "Email must not use a disposable-domain address");
440	        }
441	        return canonical;
442	    }
443	
444	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
445	    private static final int MAX_OWNERS_PER_CITY = 50;
446	
447	    /**
448	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
449	     * owners, comparing city names case-insensitively. Callers reach this only once {@code city} has
450	     * been validated non-blank.
451	     *
452	     * @param city the incoming owner's city (already validated non-blank)
453	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
454	     */
455	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
456	    private static final int MAX_OWNERS_PER_DAY = 100;
457	
458	    /**
459	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
460	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
461	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
462	     * date rolled forward to a business day), so this caps the number that may be created per day.
463	     *
464	     * @param businessDay the adjusted business-day registration date of the owner being created
465	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
466	     */
467	    /**
468	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
469	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
470	     */
471	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
472	
473	    /**
474	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
475	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
476	     * owner's registration date, otherwise {@code false}.
477	     *
478	     * @param owner the owner to map
479	     * @return the owner DTO with its bulk-signup warning flag populated
480	     */
481	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
482	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
483	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
484	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
485	        ownerDto.setMembershipPoints(points);
486	        ownerDto.setMembershipLevel(OwnerMapper.membershipLevelFor(points));
487	        return ownerDto;
488	    }
489	
490	    /**
491	     * Returns the number of owners sharing the given {@code householdId} (the household's size),
492	     * counting every existing owner that carries the same {@code householdId}. Returns {@code 0} when
493	     * {@code householdId} is {@code null}, since an owner with no postcode has no household key and so
494	     * no household.
495	     *
496	     * @param householdId the owner's computed household identifier, or {@code null} when absent
497	     * @return the number of owners in the household
498	     */
499	    private int householdSize(String householdId) {
500	        if (householdId == null) {
501	            return 0;
502	        }
503	        return (int) this.clinicService.findAllOwners().stream()
504	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
505	            .count();
506	    }
507	
508	    /**
509	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
510	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
511	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
512	     */
513	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
514	        if (registrationDate == null) {
515	            return false;
516	        }
517	        long registeredThatDay = this.clinicService.findAllOwners().stream()
518	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
519	            .count();
520	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
521	    }
522	
523	    private void requireDailyLimitNotReached(LocalDate businessDay) {
524	        long registeredThatDay = this.clinicService.findAllOwners().stream()
525	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
526	            .count();
527	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
528	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
529	        }
530	    }
531	
532	    /**
533	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
534	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
535	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
536	     * is recorded on the next business day, and every value derived from the registration date uses the
537	     * adjusted date.
538	     *
539	     * @param date the effective registration date (supplied or defaulted), never {@code null}
540	     * @return the same date, or the next Monday when {@code date} is a weekend
541	     */
542	    private static LocalDate toBusinessDay(LocalDate date) {
543	        DayOfWeek day = date.getDayOfWeek();
544	        if (day == DayOfWeek.SATURDAY) {
545	            return date.plusDays(2);
546	        }
547	        if (day == DayOfWeek.SUNDAY) {
548	            return date.plusDays(1);
549	        }
550	        return date;
551	    }
552	
553	    /** Matches a well-formed postcode: exactly four decimal digits. */
554	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
555	
556	    /**
557	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
558	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
559	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
560	     * present here and accepts any well-formed postcode.
561	     */
562	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
563	        "NSW", new int[] {2000, 2099},
564	        "VIC", new int[] {3000, 3099},
565	        "QLD", new int[] {4000, 4099});
566	
567	    /**
568	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
569	     * optional, so the request contract stays backward-compatible). When present it must be exactly
570	     * four digits and, for a city whose region is known, fall within that region's inclusive range
571	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
572	     * postcode. A malformed or out-of-range value is rejected with a 400.
573	     *
574	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
575	     * @param city the owner's city, used to look up the region whose range constrains the postcode
576	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
577	     */
578	    private void validatePostcode(String postcode, String city) {
579	        if (postcode == null) {
580	            return;
581	        }
582	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
583	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
584	        }
585	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
586	        int[] range = REGION_POSTCODES.get(region);
587	        if (range == null) {
588	            return;
589	        }
590	        int value = Integer.parseInt(postcode);
591	        if (value < range[0] || value > range[1]) {
592	            throw new InvalidFieldValueException("postcode",
593	                "Postcode must be valid for the city's region " + region);
594	        }
595	    }
596	
597	    /**
598	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
599	     * date defaults to the server date). When present it must not be later than the current server
600	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
601	     *
602	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
603	     * @throws InvalidFieldValueException if the supplied date is later than the server date
604	     */
605	    private void validateRegistrationDate(LocalDate registrationDate) {
606	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
607	            throw new InvalidFieldValueException("registrationDate",
608	                "Registration date must not be later than the current date");
609	        }
610	    }
611	
612	    private void requireCityBelowCapacity(String city) {
613	        long cityOwners = this.clinicService.findAllOwners().stream()
614	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
615	            .count();
616	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
617	            throw new CityAtCapacityException(city);
618	        }
619	    }
620	
621	    /**
622	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
623	     * of any existing owner. The key ({@code normalizedTelephone + '|' + (email or empty) + '|' +
624	     * (householdId or empty)}) is the single consolidated duplicate-detection key that replaces the
625	     * former separate telephone, email and household checks. Because the telephone is part of the
626	     * key, two members of the same household (same {@code householdId}) with different telephones
627	     * have different keys and are both allowed; only an exact full-key match is a duplicate. The key
628	     * is derived identically for the incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
629	     *
630	     * @param owner the incoming owner, with its normalized telephone, email and household identifier
631	     *              already populated
632	     * @throws DuplicateIdentityException if another owner already has this exact identity key
633	     */
634	    private void requireUniqueIdentity(Owner owner) {
635	        String identityKey = ownerMapper.toIdentityKey(owner);
636	        boolean taken = this.clinicService.findAllOwners().stream()
637	            .map(ownerMapper::toIdentityKey)
638	            .anyMatch(identityKey::equals);
639	        if (taken) {
640	            throw new DuplicateIdentityException(identityKey);
641	        }
642	    }
643	
644	    /**
645	     * Rejects the request when the incoming owner would join an existing household, unless the owner
646	     * has opted in via {@code sharesHousehold}. Because the household is keyed on {@code householdId}
647	     * (the computed hash of the normalized last name and postcode), any existing owner carrying the
648	     * same {@code householdId} is a member of the same household, so a second such owner is a
649	     * household duplicate. Setting {@code sharesHousehold} bypasses this block, declaring the owner a
650	     * genuine additional member of that household. An owner with no {@code householdId} (no postcode,
651	     * so no household key) is never a household duplicate.
652	     *
653	     * @param owner the incoming owner, with its computed {@code householdId} already populated
654	     * @param sharesHousehold whether the request opted in to joining an existing household
655	     * @throws DuplicateIdentityException if the household already exists and the owner did not opt in
656	     */
657	    private void requireNoHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
658	        if (sharesHousehold) {
659	            return;
660	        }
661	        String householdId = owner.getHouseholdId();
662	        if (householdId == null) {
663	            return;
664	        }
665	        boolean householdExists = this.clinicService.findAllOwners().stream()
666	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
667	        if (householdExists) {
668	            throw new DuplicateIdentityException(ownerMapper.toIdentityKey(owner));
669	        }
670	    }
671	
672	    /**
673	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate and
674	     * household-duplicate checks have passed, so the owner is known not to be a rejected duplicate.
675	     * When an existing owner shares this owner's household (same computed {@code householdId}) but
676	     * carries a different telephone, the owner is a possible duplicate: {@code possibleDuplicate} is
677	     * set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
678	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
679	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
680	     * duplicate. An owner with no {@code householdId} never matches, since it shares no household.
681	     *
682	     * @param owner the incoming owner, with its computed {@code householdId} and telephone populated
683	     * @param sharesHousehold whether the request opted in as a declared household member
684	     */
685	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
686	        owner.setPossibleDuplicate(false);
687	        owner.setPossibleDuplicateOf(null);
688	        if (sharesHousehold) {
689	            return;
690	        }
691	        String householdId = owner.getHouseholdId();
692	        if (householdId == null) {
693	            return;
694	        }
695	        String telephone = owner.getTelephone();
696	        this.clinicService.findAllOwners().stream()
697	            .filter(existing -> householdId.equals(existing.getHouseholdId())
698	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
699	            .min(java.util.Comparator.comparing(Owner::getId))
700	            .ifPresent(match -> {
701	                owner.setPossibleDuplicate(true);
702	                owner.setPossibleDuplicateOf(match.getId());
703	            });
704	    }
705	
706	    /**
707	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
708	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
709	     * comparisons are case-insensitive.
710	     */
711	    private static String normalizeForHousehold(String value) {
712	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
713	    }
714	
715	    /**
716	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
717	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
718	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
719	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
720	     * value normalizes to the empty string, so the required-field check rejects an address that is
721	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
722	     *
723	     * @param address the raw address value from the request (may be {@code null})
724	     * @return the normalized address, or the empty string when blank after normalization
725	     */
726	    private static String normalizeAddress(String address) {
727	        if (address == null) {
728	            return "";
729	        }
730	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
731	        if (collapsed.isEmpty()) {
732	            return "";
733	        }
734	        String[] tokens = collapsed.split(" ");
735	        StringBuilder sb = new StringBuilder();
736	        for (String token : tokens) {
737	            String expanded = switch (token) {
738	                case "ST" -> "STREET";
739	                case "RD" -> "ROAD";
740	                case "AVE" -> "AVENUE";
741	                default -> token;
742	            };
743	            if (sb.length() > 0) {
744	                sb.append(' ');
745	            }
746	            sb.append(expanded);
747	        }
748	        return sb.toString();
749	    }
750	
751	    /**
752	     * Composes the stored/returned {@code address} from the normalized structured lines: the
753	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
754	     * appended when {@code addressLine2} is present (non-empty). Both arguments are already
755	     * normalized via {@link #normalizeAddress(String)}.
756	     *
757	     * @param normalizedAddressLine1 the normalized first address line (non-empty)
758	     * @param normalizedAddressLine2 the normalized second address line, or the empty string when absent
759	     * @return the composed address string
760	     */
761	    private static String composeAddress(String normalizedAddressLine1, String normalizedAddressLine2) {
762	        if (normalizedAddressLine2.isEmpty()) {
763	            return normalizedAddressLine1;
764	        }
765	        return normalizedAddressLine1 + " " + normalizedAddressLine2;
766	    }
767	
768	    /**
769	     * Derives the stable household identifier for an owner from its last name and postcode as the
770	     * upper-cased first 12 hex characters of the SHA-256 digest of
771	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
772	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
773	     * identifier is a deterministic function of the normalized last name and postcode, owners that
774	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
775	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
776	     * postcode and there is then nothing to key on.
777	     *
778	     * @param lastName the owner's last name (already validated non-blank)
779	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
780	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
781	     */
782	    private static String householdIdFor(String lastName, String postcode) {
783	        if (postcode == null || postcode.isBlank()) {
784	            return null;
785	        }
786	        String normalizedLastName = normalizeForHousehold(lastName);
787	        try {
788	            byte[] digest = MessageDigest.getInstance("SHA-256")
789	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
790	            StringBuilder sb = new StringBuilder();
791	            for (byte b : digest) {
792	                sb.append(String.format("%02X", b));
793	            }
794	            return sb.substring(0, 12);
795	        }
796	        catch (NoSuchAlgorithmException e) {
797	            throw new IllegalStateException("SHA-256 not available", e);
798	        }
799	    }
800	}
