108	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Used to derive an
109	     * owner's locality from its postcode in preference to its city.
110	     */
111	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
112	        "NSW", new int[] {2000, 2099},
113	        "VIC", new int[] {3000, 3099},
114	        "QLD", new int[] {4000, 4099});
