116	    /**
117	     * Derives the owner's canonical region, the {@code REGION} component of its {@code customerCode}.
118	     * The postcode takes precedence: when the owner has a well-formed 4-digit postcode that falls
119	     * within a known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
120	     * 4000-4099}), that region is returned. Otherwise the region is looked up from the fixed
121	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
122	     * yielding {@code 'UNKNOWN'} when the city is not in the table. Preferring the postcode returns
123	     * the same region for known cities but disambiguates cities that share a name.
124	     */
125	    default String toRegion(Owner owner) {
126	        if (owner == null) {
127	            return null;
128	        }
129	        String regionByPostcode = regionForPostcode(owner.getPostcode());
130	        if (regionByPostcode != null) {
