157	
158	    /**
159	     * Derives the owner's {@code timezone} as the IANA timezone name mapped from its locality/region
160	     * via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
161	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Returns {@code null} when the
162	     * owner's region is not one of the tabled regions.
163	     */
164	    @Named("toTimezone")
165	    default String toTimezone(Owner owner) {
