171	
172	    /**
173	     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
174	     * {@code null} when the postcode is absent, malformed, or in no known range.
175	     */
176	    private static String regionForPostcode(String postcode) {
177	        if (postcode == null || !postcode.matches("\\d{4}")) {
178	            return null;
179	        }
180	        int value = Integer.parseInt(postcode);
181	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
182	            int[] range = entry.getValue();
