218	        String digits = telephone.substring(1);
219	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
220	        String countryCode = digits.substring(0, countryCodeLength);
221	        String national = digits.substring(countryCodeLength);
222	        StringBuilder sb = new StringBuilder("+").append(countryCode);
223	        for (int i = 0; i < national.length(); i++) {
224	            if (i % 3 == 0) {
225	                sb.append(' ');
226	            }
227	            sb.append(national.charAt(i));
