299	    static int membershipPointsFor(Owner owner, int householdSize) {
300	        int points = 0;
301	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
302	        if (hasEmail) {
303	            points += 2;
304	        }
305	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
306	        if (noNamesakes) {
307	            points += 1;
308	        }
309	        if (householdSize >= 3) {
310	            points += 2;
311	        }
312	        boolean tenured = owner.getRegistrationDate() != null
313	            && ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now()) > 365;
314	        if (tenured) {
315	            points += 3;
316	        }
