349	        }
350	        int sum = 0;
351	        boolean dbl = true;
352	        String code = owner.getCustomerCode();
353	        for (int i = code.length() - 1; i >= 0; i--) {
354	            char c = code.charAt(i);
355	            if (c < '0' || c > '9') {
356	                continue;
357	            }
358	            int d = c - '0';
359	            if (dbl) {
360	                d *= 2;
361	                if (d > 9) {
362	                    d -= 9;
363	                }
364	            }
365	            sum += d;
366	            dbl = !dbl;
367	        }
368	        return (10 - (sum % 10)) % 10;
369	    }
